/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import page2020.util.EmptyUtil;public class B4col extends B4box<B4col> {	public static final String col = "col";	public static final String sm = "sm";	public static final String md = "md";	public static final String lg = "lg";	public static final String xl = "xl";	public static final String auto = "col-auto";	public static int[] numbers(int... numbers) {		if (numbers != null && numbers.length > 0) {			boolean valid = false;			int[] array = new int[numbers.length];			for (int i=0; i < numbers.length; i++) {				if (numbers[i] >= 1 && numbers[i] <= 12) {					array[i] = numbers[i];					valid = true;				} else {					array[i] = 0;				}			}			return valid ? array : null;		}		return null;	}	public static int[] numbers(String device) {		String[] tokens = null;		if (EmptyUtil.not(device)) {			if (device.contains(",")) {				tokens = device.split(",");			} else {				tokens = new String[] { device };			}		} else {			return null;		}		int[] numbers = new int[tokens.length];			boolean valid = false;		for (int i=0; i < tokens.length; i++) {			try {				numbers[i] = Integer.valueOf(tokens[i].trim()).intValue();				valid = true;			} catch (Exception ex) {				numbers[i] = 0;			}		}		return valid ? numbers(numbers) : null;	}	public static int[] two(int[] numbers) {		int len = numbers.length;		int[] devices = new int[len];		for (int i=0; i < len; i++) {			devices[i] = (numbers[i] >= 12) ? 12 : (12 - numbers[i]);		}		return devices;	}	public static int[] three(int[] numbers) {		int len = numbers.length;		int[] devices = new int[len];		for (int i=0; i < len; i++) {			int number = numbers[i];			if (number % 2 > 0) {				number -= 1;			}			if (number > 10) {				number = 10;			}			if (number < 2) {				number = 2;			}			numbers[i] = number;			devices[i] = (int) ((12 - number) / 2);		}		return devices;	}	private int[] numbers = null;	private boolean automatical = false;	public B4col() {		super();	}	public B4col(boolean auto) {		this.automatical = auto;	}	public B4col device(int... numbers) {		this.numbers = numbers(numbers);		return this;	}	public B4col device(String device) {		this.numbers = numbers(device);		return this;	}	@Override	public void build() {		if (this.automatical) {			super.cssClass(auto);		} else if (this.numbers != null) {			for (int i=0; i < this.numbers.length; i++) {				if (this.numbers[i] != 0) {					String deviceClass = null;					switch (i) {					case 0:						deviceClass = String.format("%s-%d", col, this.numbers[i]);						break;					case 1:						deviceClass = String.format("%s-%s-%d", col, sm, this.numbers[i]);						break;					case 2:						deviceClass = String.format("%s-%s-%d", col, md, this.numbers[i]);						break;					case 3:						deviceClass = String.format("%s-%s-%d", col, lg, this.numbers[i]);						break;					case 4:						deviceClass = String.format("%s-%s-%d", col, xl, this.numbers[i]);						break;					default:						continue;					}					super.cssClass(deviceClass);				}			}		}				super.build();	}	public int[] getNumbers() {		return numbers;	}	public void setNumbers(int[] numbers) {		this.numbers = numbers;	}}